<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderRef;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Accessor\UserFederatedIdentityLoginProviderAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserFederatedIdentityLoginProviderAccessor trait.
 *
 * Covers null default, string/VO assignment via withLoginProvider,
 * getLoginProvider/loginProvider accessors, and isLoginProviderChanged with/without original.
 */
class UserFederatedIdentityLoginProviderAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withLoginProvider creates a new instance with the LoginProvider set
     * from a string value, and getLoginProvider returns the primitive string.
     */
    public function testWithLoginProviderFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserFederatedIdentityLoginProviderAccessorUnitTest();

        // Act
        $result = $holder->withLoginProvider(new TenantLoginProviderRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new TenantLoginProviderRef('one'), $result->getLoginProvider());
    }
    /**
     * Asserts that withloginProvider has access to the value object
     * from a string value, and getLoginProvider returns the primitive string.
     */
    public function testWithLoginProviderFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserFederatedIdentityLoginProviderAccessorUnitTest();

        // Act
        $result = $holder->withLoginProvider(new TenantLoginProviderRef('one'));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new TenantLoginProviderRef('one'), $result->loginProvider()->value());
    }
    public function testChangedLoginProvider(): void
    {
        // Arrange
        $holder = new ImplWithUserFederatedIdentityLoginProviderAccessorUnitTest()->withLoginProvider(new TenantLoginProviderRef('one'));
        $original = $holder->withLoginProvider(new TenantLoginProviderRef('one'));
        $same = $holder->withLoginProvider(new TenantLoginProviderRef('one'));
        $modified = $holder->withLoginProvider(new TenantLoginProviderRef('other'));

        // Act
        $withSame = $original->isLoginProviderChanged($same);
        $withDiferent = $original->isLoginProviderChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserFederatedIdentityLoginProviderAccessorUnitTest
{
    use UserFederatedIdentityLoginProviderAccessor;
}
